/* Buildless reusable pilot. All state is in-memory; no network, authentication or external writes. */
const state={lang:'de',course:'T',step:0,role:'applicant',uploads:{},chat:[],brief:'',application:{course:'T',language:'B1',start:'Noch offen'},submitted:false,attendance:{},tasks:{},tab:'all'};
const t=(de,en)=>state.lang==='de'?de:en;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arrow='<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg>';
const route=()=>location.hash.slice(1)||'/';
const link=(label,to,kind='')=>`<a class="btn ${kind}" href="#${to}">${label}${arrow}</a>`;
const button=(label,action,kind='',extra='')=>`<button class="btn ${kind}" data-action="${action}" ${extra}>${label}${arrow}</button>`;
const badge=(label,kind='')=>`<span class="status ${kind}">${label}</span>`;
const panel=(title,content,cls='')=>`<section class="panel ${cls}"><h3>${title}</h3>${content}</section>`;
const notice=content=>`<div class="notice">${content}</div>`;
const heading=(eyebrow,title,description)=>`<div class="page-heading"><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${description}</p></div>`;
const courses=[{id:'T',title:['Technik & Naturwissenschaft','Engineering & science'],desc:['Für deinen Weg in technische, mathematische und naturwissenschaftliche Studienrichtungen.','A pathway towards technical, mathematical and natural science programmes.'],symbol:'T',tag:'T-Kurs'},{id:'M',title:['Medizin & Biologie','Medicine & biology'],desc:['Vorbereitung für medizinische, biologische und verwandte Studienrichtungen.','Preparation for medical, biological and related fields of study.'],symbol:'M',tag:'M-Kurs'},{id:'W',title:['Wirtschaft & Gesellschaft','Business & society'],desc:['Orientierung für wirtschafts- und sozialwissenschaftliche Studienrichtungen.','Orientation towards business and social science programmes.'],symbol:'W',tag:'W-Kurs'},{id:'G',title:['Geisteswissenschaften','Humanities'],desc:['Sprachliche und fachliche Vorbereitung auf geisteswissenschaftliche Studienwege.','Language and subject preparation for humanities pathways.'],symbol:'G',tag:'G-Kurs'},{id:'TM',title:['T + M kombiniert','T + M combined'],desc:['Den kombinierten Bildungsweg gemeinsam mit der Beratung prüfen.','Discuss the combined pathway with the admissions team.'],symbol:'+',tag:'T+M'},{id:'Deutsch',title:['Deutsch lernen','Learn German'],desc:['Sprachkurse A1 bis C1 als Teil deines individuellen Bildungswegs.','German courses A1 to C1 as part of your individual learning journey.'],symbol:'Aa',tag:'A1 — C1'},{id:'TestAS',title:['TestAS-Vorbereitung','TestAS preparation'],desc:['Orientierung und Vorbereitung für den TestAS-Bildungsweg.','Orientation and preparation for the TestAS pathway.'],symbol:'✓',tag:'TestAS'}];
const courseCard=c=>`<a class="course-card" href="#/course/${c.id}"><div class="course-symbol">${c.symbol}</div><div class="meta">${c.tag}</div><h3>${t(...c.title)}</h3><p>${t(...c.desc)}</p><span class="card-link">${t('Kurs kennenlernen','Explore programme')} ${arrow}</span></a>`;
function header(){return `<div class="pilot"><strong>${t('KONZEPTPILOT · STUDIENKOLLEG AACHEN','CONCEPT PILOT · STUDIENKOLLEG AACHEN')}</strong><span>${t('Nur Beispieldaten · Keine echte Bewerbung oder Anmeldung','Sample data only · No real application or sign-in')}</span></div><header class="header"><a class="brand" href="#/" aria-label="${t('Studienkolleg Aachen Startseite','Studienkolleg Aachen home')}"><img class="brand-logo" src="assets/studienkolleg-logo.png" alt="Studienkolleg Aachen"></a><nav class="navigation" aria-label="${t('Hauptnavigation','Main navigation')}">${[['/',t('Entdecken','Discover')],['/courses',t('Kurse','Programmes')],['/admission',t('Dein Weg','Your journey')],['/help',t('Beratung','Advice')]].map(([r,l])=>`<a href="#${r}" class="${route()===r?'active':''}">${l}</a>`).join('')}</nav><div class="header-actions"><button class="lang" data-action="language" aria-label="Change language">${state.lang.toUpperCase()} ⌄</button>${link(t('Mein Portal','My portal'),'/portal/applicant','small secondary')}</div></header>`}
function home(){return `<div class="breadcrumb">${t('Willkommen in Aachen','Welcome to Aachen')} <span> / </span> ${t('Deine Zukunft beginnt hier','Your future starts here')}</div><section class="hero"><div class="hero-grid"><div><span class="eyebrow">${t('Dein Weg an eine deutsche Hochschule','Your pathway to a German university')}</span><h1>${t('Große Pläne.<br>Ein klarer <em>Weg.</em>','Big ambitions.<br>A clear <em>path.</em>')}</h1><p class="lead">${t('Studienvorbereitung, Deutsch und persönliche Orientierung. Entdecke den Bildungsweg, der zu deinem Ziel passt — Schritt für Schritt.','University preparation, German language and personal guidance. Discover a learning pathway that fits your ambitions — one step at a time.')}</p><div class="actions">${link(t('Meinen Kurs finden','Find my programme'),'/courses')}${link(t('So startest du','How to get started'),'/admission','secondary')}</div><div class="hero-caption">${t('Orientierung. Vorbereitung. Nächster Schritt.','Explore. Prepare. Take your next step.')}</div></div><div class="hero-photo"><img src="assets/hero-woman.webp" alt="${t('Bildmotiv der bestehenden Studienkolleg-Website','Image from the existing Studienkolleg website')}"><span class="photo-label">STUDIENKOLLEG AACHEN<br><small>${t('Dein nächster Schritt.','Your next step.')}</small></span></div></div></section><section class="section"><div class="section-head"><div><span class="eyebrow">${t('Finde deine Richtung','Find your direction')}</span><h2>${t('Was möchtest du studieren?','What would you like to study?')}</h2></div>${link(t('Alle Kurse','All programmes'),'/courses','ghost small')}</div><div class="course-grid">${courses.slice(0,3).map(courseCard).join('')}</div></section><section class="section"><div class="section-head"><div><span class="eyebrow">${t('Von der Idee zur Bewerbung','From ambition to application')}</span><h2>${t('Du musst nicht alles schon wissen.','You don’t need every answer yet.')}</h2></div></div>${journey()}</section><section class="section blue-section split"><div><span class="eyebrow">${t('Mehr als ein Kurs','More than a programme')}</span><h2 class="quote-title">${t('Ankommen. Sprache finden.<br>Deinen nächsten Schritt gehen.','Settle in. Find your voice.<br>Take the next step.')}</h2><p>${t('Sprachlernen, Prüfungen und Ankommen gehören zusammen. Wir zeigen dir, welche Themen du mit der Beratung klären kannst.','Language learning, examinations and arrival belong together. Explore the topics to discuss with the advisory team.')}</p></div><div class="text-links"><a href="#/course/Deutsch">${t('Deutsch A1 bis C1','German A1 to C1')} ${arrow}</a><a href="#/services">${t('Prüfungen & Vorbereitung','Exams & preparation')} ${arrow}</a><a href="#/services/housing">${t('Wohnen & Ankommen','Housing & arrival')} ${arrow}</a><a href="#/help">${t('Persönliche Beratung','Personal guidance')} ${arrow}</a></div></section>`}
function journey(){return `<div class="journey-list">${[[t('Orientieren','Explore'),t('Lerne die Kurse und mögliche Studienrichtungen kennen.','Explore programmes and possible fields of study.')],[t('Vorbereiten','Prepare'),t('Stelle deine Unterlagen und Sprachkenntnisse zusammen.','Bring together your documents and language information.')],[t('Prüfen lassen','Get reviewed'),t('Die Zulassungsberatung prüft deinen individuellen Weg.','Admissions advisers review your individual pathway.')],[t('Nächsten Schritt planen','Plan your next step'),t('Besprich Angebot, Vorbereitung und Ankunft persönlich.','Discuss your offer, preparation and arrival personally.')]].map(([title,desc],i)=>`<a class="journey-item" href="#${i===0?'/courses':i===1?'/apply':'/admission'}"><span class="number">0${i+1}</span><h3>${title}</h3><p>${desc}</p></a>`).join('')}</div>`}
function courseList(){let list=state.tab==='language'?courses.filter(c=>c.id==='Deutsch'):state.tab==='prep'?courses.filter(c=>c.id!=='Deutsch'):courses;return heading(t('Unser Kursangebot','Our programmes'),t('Dein Ziel. Deine Richtung.','Your ambition. Your direction.'),t('Entdecke die Studienvorbereitung und Sprachkurse. Welcher Weg fachlich passt, wird in der persönlichen Prüfung geklärt.','Explore preparatory and language programmes. Your individual eligibility is assessed by the admissions team.'))+`<section class="section"><div class="tabs" role="group" aria-label="${t('Kursfilter','Programme filter')}">${[['all',t('Alle Angebote','All programmes')],['prep',t('Studienvorbereitung','University preparation')],['language',t('Deutsch','German')]].map(([v,l])=>`<button class="tab ${state.tab===v?'active':''}" data-action="filter" data-value="${v}">${l}</button>`).join('')}</div><div class="course-grid">${list.map(courseCard).join('')}</div>${notice(t('Kursstarts, Gebühren und verbindliche Voraussetzungen werden im Pilot nicht als Live-Daten dargestellt. Bitte im echten Beratungsgespräch bestätigen lassen.','Start dates, fees and binding requirements are not live data in this pilot. Please confirm them in a real advisory conversation.'))}</section>`}
const courseGuidance={
T:[['Technische Ideen verstehen. Fachlich weiterdenken.','Understand technical ideas. Develop subject confidence.'],['Du interessierst dich für Ingenieurwissenschaften, Mathematik oder Naturwissenschaften? Der T-Schwerpunkt ist ein Ausgangspunkt für deine Kurswahl. Bring deine gewünschten Studiengänge mit in die Beratung.','Interested in engineering, mathematics or natural sciences? The T focus is a starting point for your programme choice. Bring your intended degree programmes to your advisory conversation.'],['Welche mathematischen und naturwissenschaftlichen Grundlagen sollte ich auffrischen?','Which mathematics and science foundations should I refresh?']],
M:[['Dein Interesse gilt dem Leben.','Your interest is in life sciences.'],['Medizinische und biologische Studienrichtungen stellen eigene Anforderungen. Mit dem M-Schwerpunkt kannst du deinen möglichen Vorbereitungsweg erkunden und die Passung zu deinem Studienziel besprechen.','Medical and biological fields have their own requirements. Explore the M focus and discuss how this pathway could fit your intended degree.'],['Wie bereite ich mich sprachlich und fachlich auf meinen medizinischen Studienwunsch vor?','How can I prepare linguistically and academically for my intended medical degree?']],
W:[['Wirtschaft verstehen. Zusammenhänge erkennen.','Understand business. Make connections.'],['Du möchtest wirtschaftliche oder gesellschaftliche Fragen studieren? Nutze den W-Schwerpunkt zur Orientierung und kläre, welcher Vorbereitungsweg für deinen Wunschstudiengang sinnvoll ist.','Interested in studying business or social questions? Explore the W focus and discuss a suitable pathway for your chosen degree.'],['Passt mein Wunschstudiengang zum W-Schwerpunkt?','Does my intended degree fit the W focus?']],
G:[['Mit Sprache neue Perspektiven entdecken.','Discover new perspectives through language.'],['Du interessierst dich für geisteswissenschaftliche Studienrichtungen? Der G-Schwerpunkt hilft bei der Orientierung. Besprich dein Studienziel und deine sprachliche Vorbereitung gemeinsam.','Interested in the humanities? The G focus offers a starting point. Discuss your intended degree and language preparation together.'],['Welche sprachlichen Anforderungen sind für mein Studienziel wichtig?','Which language requirements matter for my intended degree?']],
TM:[['Zwei Richtungen gemeinsam betrachten.','Explore two directions together.'],['Wenn technische und medizinisch-biologische Interessen zusammenkommen, lohnt sich ein Gespräch zum kombinierten T+M-Weg. Kläre den fachlichen Rahmen und deinen individuellen Bedarf.','When technical and medical or biological interests overlap, discuss the combined T+M pathway. Clarify its scope and your individual preparation needs.'],['Wann ist der kombinierte T+M-Weg für mein Ziel sinnvoll?','When is the combined T+M pathway suitable for my goal?']],
Deutsch:[['Mehr Sicherheit. Wort für Wort.','More confidence. Word by word.'],['Ob du mit Deutsch beginnst oder vorhandene Kenntnisse ausbauen möchtest: A1 bis C1 bietet unterschiedliche Einstiegspunkte. Besprich deinen aktuellen Stand und wofür du Deutsch im Alltag, im Studium oder im Beruf brauchst.','Whether you are starting German or building on existing skills, A1 to C1 offers different entry points. Discuss your current level and how you plan to use German in everyday life, study or work.'],['Wie wird mein Einstiegsniveau geklärt und welcher Kurs passt zu meinem Lernziel?','How is my starting level assessed and which course fits my learning goal?']],
TestAS:[['Den nächsten Test gezielt vorbereiten.','Prepare for your next test with purpose.'],['Lerne den TestAS-Vorbereitungsweg kennen und kläre, welche Rolle der Test für deine konkrete Hochschulbewerbung spielt. Anforderungen und Anerkennung hängen von deinem Ziel ab.','Explore the TestAS preparation pathway and clarify the role of the test in your specific university application. Requirements and recognition depend on your goal.'],['Welche TestAS-Anforderungen stellt meine Wunschhochschule?','What TestAS requirements does my preferred university have?']]};
function courseDetail(id){const c=courses.find(x=>x.id===id)||courses[0];const g=courseGuidance[c.id];return heading(`${c.tag} · ${t('Kurs entdecken','Explore programme')}`,t(...c.title),t(...c.desc))+`<section class="section"><div class="info-grid">${panel(t(...g[0]),`<p>${t(...g[1])}</p>${link(t('Meinen Einstieg vorbereiten','Prepare my next step'),'/apply?course='+c.id)}`)}${panel(t('Das bringst du ins Gespräch mit','Bring these to your conversation'),`<ul class="check-list"><li>${c.id==='Deutsch'?t('Wofür du Deutsch lernen möchtest','Why you want to learn German'):t('Deinen Wunschstudiengang und offene Fragen','Your intended degree and open questions')}</li><li>${t('Deine bisherige Lern- und Schulerfahrung','Your previous learning and school experience')}</li><li>${t('Deinen aktuellen Deutschstand','Your current German level')}</li><li>${t('Deine zeitlichen Vorstellungen','Your preferred timing')}</li></ul>`)}${panel(t('Eine gute Frage für deinen nächsten Schritt','A good question for your next step'),`<h3 class="quote-title" style="font-size:25px">${t(...g[2])}</h3><p>${t('Halte diese Frage in deinem Beratungsbrief fest. Gemeinsam lassen sich Inhalte, Einstieg und aktuelle Kursmöglichkeiten genauer klären.','Add this question to your advisory brief. A personal conversation can clarify content, entry level and current programme options.')}</p><div class="actions">${button(t('Frage im Beratungsbrief notieren','Add question to advisory brief'),'course-brief','',`data-value="${c.id}"`)}${link(t('So funktioniert der Einstieg','How to get started'),'/admission','secondary')}</div>`,'wide')}</div></section>`}
function admission(){return heading(t('Bewerbung & Aufnahme','Application & admission'),t('Ein Schritt nach dem anderen.','One step at a time.'),t('Du bringst dein Ziel mit. Die persönliche Prüfung macht daraus einen passenden nächsten Schritt — ohne automatische Zulassungsversprechen.','Bring your ambitions. A personal review helps identify a suitable next step — without automatic promises of admission.'))+`<section class="section">${journey()}<div class="info-grid" style="margin-top:30px">${panel(t('Das kannst du vorbereiten','What you can prepare'),`<ul class="check-list"><li>${t('Abschlusszeugnis und Notenübersicht','School certificate and transcript')}</li><li>${t('Vorhandene Sprachzertifikate','Existing language certificates')}</li><li>${t('Informationen zum gewünschten Studium','Your intended field of study')}</li><li>${t('Offene Fragen zur Vorbereitung und Ankunft','Questions about preparation and arrival')}</li></ul><p class="subtle">${t('Die genaue Unterlagenliste wird für den individuellen Fall bestätigt. Im Pilot bitte keine echten Dokumente hochladen.','The exact document list is confirmed for each case. Please do not upload real documents into this pilot.')}</p>`)}${panel(t('Menschen entscheiden','People make the decisions'),`<p>${t('Die Zulassungsberatung prüft deine Unterlagen. Rückfragen, Angebote und Freigaben bleiben nachvollziehbar. Ein vorbereiteter Antrag ist noch keine verbindliche Anmeldung.','Admissions staff review your documents. Questions, offers and approvals remain transparent. A prepared application is not a binding enrolment.')}</p>${notice(t('Visum und Hochschulzulassung werden von den zuständigen Behörden und Hochschulen entschieden.','Visa and university admission decisions remain with the relevant authorities and universities.'))}${link(t('Pilot-Bewerbung starten','Start pilot application'),'/apply')}`)}</div></section>`}
// Keep canonical draft values stable across display-language changes.
function applicationChoiceLabel(value){const labels={'Noch offen':['Noch offen','Not set'],'Nächstmöglicher Einstieg':['Nächstmöglicher Einstieg','Next available intake'],'Späterer Einstieg':['Späterer Einstieg','Later intake']};return Object.prototype.hasOwnProperty.call(labels,value)?t(...labels[value]):String(value||t('Noch offen','Not set'))}
function applicationDraftDetails(){return `<div class="task-row"><strong>${t('Zeitliche Orientierung','Preferred timing')}</strong><span>${esc(applicationChoiceLabel(state.application.start))}</span></div><div class="task-row"><strong>${t('Land des letzten Abschlusses · Beispiel','Country of last qualification · sample')}</strong><span>${esc(state.application.educationCountry||t('Noch offen','Not set'))}</span></div><div class="task-row"><strong>${t('Reisepass · ergänzender Musternachweis','Passport · supplementary sample evidence')}</strong><span>${state.application.passport?t('Muster ergänzt · Prüfung offen','Sample added · review pending'):t('Kein Muster ergänzt','No sample added')}</span></div>`}
function application(){let content='';const labels=[t('Bildungsziel','Study goal'),t('Unterlagen','Documents'),t('Beratung','Guidance'),t('Übersicht','Review')];if(state.submitted)return heading(t('Demo-Bewerbung','Demo application'),t('Dein Entwurf ist vorbereitet.','Your draft is ready.'),t('Nichts wurde versendet. Im Bewerberportal kannst du den weiteren Ablauf mit Beispieldaten erkunden.','Nothing was submitted. Explore the next steps in the applicant portal using sample data.'))+`<section class="section">${panel(t('Nächster Schritt: persönliche Prüfung','Next step: personal review'),`<p>${t('Der Demo-Vorgang zeigt, wie Unterlagen, Beratung und Status später zusammenkommen. Es wurde keine echte Akte angelegt.','This demo shows how documents, guidance and status can come together. No real record has been created.')}</p><div class="actions">${link(t('Zum Bewerberportal','Open applicant portal'),'/portal/applicant')}${button(t('Entwurf weiter bearbeiten','Edit draft'),'edit-application','secondary')}</div>`)}</section>`;if(state.step===0)content=`<h3>${t('Wohin soll dein Weg führen?','Where would you like to go?')}</h3><p>${t('Für diesen Pilot reichen unverbindliche Auswahlwerte. Bitte keine persönlichen Daten eingeben.','Non-binding selections are enough for this pilot. Please do not enter personal data.')}</p><div class="form-row"><label class="field">${t('Interessanter Kurs','Programme of interest')}<select data-field="course">${courses.map(c=>`<option value="${c.id}" ${state.application.course===c.id?'selected':''}>${c.tag} · ${t(...c.title)}</option>`).join('')}</select></label><label class="field">${t('Deutschkenntnisse (Selbstauskunft)','German level (self-reported)')}<select data-field="language">${['Noch offen','A1','A2','B1','B2','C1'].map(v=>`<option value="${esc(v)}" ${state.application.language===v?'selected':''}>${esc(applicationChoiceLabel(v))}</option>`).join('')}</select></label></div><label class="field">${t('Zeitliche Orientierung','Preferred timing')}<select data-field="start">${['Noch offen','Nächstmöglicher Einstieg','Späterer Einstieg'].map(v=>`<option value="${esc(v)}" ${state.application.start===v?'selected':''}>${esc(applicationChoiceLabel(v))}</option>`).join('')}</select></label>`;
if(state.step===1)content=`<h3>${t('Unterlagen übersichtlich sammeln.','Keep your documents together.')}</h3><p>${t('Die Buttons fügen ausschließlich Musterdateien hinzu. Es gibt keinen echten Upload.','These buttons only add sample files. There is no real upload.')}</p>${documentRows(true)}`;
if(state.step===2)content=`<h3>${t('Was möchtest du besprechen?','What would you like to discuss?')}</h3><p>${t('Wähle ein Beratungsthema für deinen Demo-Entwurf. Es wird keine Terminanfrage versendet.','Choose an advisory topic for your demo draft. No appointment request is sent.')}</p><div class="tabs">${[t('Kurswahl','Programme choice'),t('Sprachstand','Language level'),t('Ankunft','Arrival')].map(x=>button(x,'topic','secondary',`data-value="${x}"`)).join('')}</div><label class="field">${t('Dein Beratungsbrief (nur fiktive Angaben)','Your advisory brief (fictional details only)')}<textarea data-field="brief" placeholder="${t('Zum Beispiel: Ich möchte den T-Kurs kennenlernen.','For example: I would like to learn about the T programme.')}">${esc(state.brief)}</textarea></label>${notice(t('Für echte Beratung werden Kontaktangaben in einem freigegebenen, geschützten Verfahren erhoben — nicht in diesem Pilot.','For real guidance, contact details will be collected through an approved secure process — not in this pilot.'))}`;
if(state.step===3)content=`<h3>${t('Alles auf einen Blick.','Everything at a glance.')}</h3><div class="task-row"><strong>${t('Kursinteresse','Programme')}</strong>${badge(esc(state.application.course),'blue')}</div><div class="task-row"><strong>${t('Deutsch (Selbstauskunft)','German (self-reported)')}</strong>${esc(applicationChoiceLabel(state.application.language))}</div>${applicationDraftDetails()}<div class="task-row"><strong>${t('Musterunterlagen','Sample documents')}</strong>${Object.keys(state.uploads).length} / 3</div><div class="task-row"><strong>${t('Beratungsbrief','Advisory brief')}</strong>${state.brief?t('Vorbereitet','Prepared'):t('Noch offen','Not set')}</div>${notice(t('Du schließt nur den Demo-Entwurf ab. Kein Versand, keine Zulassungsentscheidung, kein Vertrag und keine Zahlung.','You are only completing a demo draft. No submission, admission decision, contract or payment.'))}`;
return heading(t('Bewerbung vorbereiten · Demo','Prepare application · Demo'),t('Dein nächster Schritt beginnt hier.','Your next step starts here.'),t('Ein geführter Entwurf — ohne Registrierung, Datenübertragung oder verbindliche Anmeldung.','A guided draft — no registration, data transmission or binding enrolment.'))+`<section class="section"><div class="stepper">${labels.map((l,i)=>`<button data-action="step" data-value="${i}" class="${state.step===i?'current':''}" aria-current="${state.step===i?'step':'false'}"><b>0${i+1}</b>${l}</button>`).join('')}</div><div class="panel">${content}<div class="actions" style="justify-content:space-between">${state.step?button(t('Zurück','Back'),'back','secondary'):link(t('Kurse ansehen','View programmes'),'/courses','secondary')}${button(state.step===3?t('Demo-Entwurf abschließen','Complete demo draft'):t('Weiter','Continue'),state.step===3?'complete':'next')}</div></div></section>`}
const docNames=()=>[t('Abschlusszeugnis','School certificate'),t('Notenübersicht','Transcript'),t('Sprachnachweis','Language certificate')];
function documentRows(upload=false){return docNames().map((name,i)=>`<div class="file-row"><div class="file-main"><span class="file-icon">▤</span><div><strong>${name}</strong><small>${state.uploads[i]?t('Musterdatei hinzugefügt · Prüfung offen','Sample file added · Review pending'):t('Demo-Unterlage · noch offen','Demo document · pending')}</small></div></div>${upload?button(state.uploads[i]?t('Muster ansehen','View sample'):t('Muster hinzufügen','Add sample'),state.uploads[i]?'document':'upload','small secondary',`data-value="${i}"`):button(t('Vorschau','Preview'),'document','small secondary',`data-value="${i}"`)}</div>`).join('')}
function help(){return heading(t('Orientierung & Beratung','Orientation & advice'),t('Gute Fragen bringen dich weiter.','Good questions move you forward.'),t('Finde erste Antworten oder bereite dein Anliegen für eine persönliche Beratung vor.','Find initial answers or prepare your questions for a personal advisory conversation.'))+`<section class="section"><div class="faq">${[[t('Welcher Kurs passt zu meinem Studium?','Which programme fits my degree?'),t('Der passende Schwerpunkt hängt von deinem Studienziel und deiner Vorbildung ab. Die Kursübersicht hilft bei der Orientierung; die individuelle Eignung prüft die Zulassungsberatung.','Your subject focus depends on your intended degree and prior education. Explore the programme overview; admissions advisers assess individual eligibility.')],[t('Kann ich mich direkt im Pilot anmelden?','Can I enrol through this pilot?'),t('Nein. Dieser Pilot zeigt eine klickbare Oberfläche mit fiktiven Angaben. Es werden keine Bewerbungen, Zahlungen, Verträge oder echten Uploads verarbeitet.','No. This pilot is a clickable interface with fictional data. It does not process applications, payments, contracts or real uploads.')],[t('Ist mein Schulabschluss ausreichend?','Is my school qualification sufficient?'),t('Das ist eine individuelle fachliche Prüfung anhand deiner Unterlagen und der geltenden Anforderungen. Der Demo-Assistent trifft keine Zulassungsentscheidung.','This requires an individual review of your documents against applicable requirements. The demo assistant does not make admissions decisions.')],[t('Sind Unterkunft und Visum garantiert?','Are accommodation and a visa guaranteed?'),t('Nein. Eine Wohnanfrage ist keine Reservierung. Über Visa entscheiden die zuständigen Behörden. Die Beratung kann die nächsten Schritte mit dir klären.','No. A housing enquiry is not a reservation. Visa decisions are made by the relevant authorities. Advisers can discuss the next steps with you.')],[t('Wo finde ich Gebühren und Kursstarts?','Where can I find fees and start dates?'),t('Verbindliche Gebühren, Kapazitäten und Termine müssen durch das Studienkolleg bestätigt werden. Dieser Konzeptpilot erfindet keine Preise oder verfügbaren Plätze.','Binding fees, capacity and dates must be confirmed by Studienkolleg. This concept pilot does not invent prices or available places.')]].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div><div class="actions">${button(t('Beratungsbrief erstellen','Create advisory brief'),'brief')}${button(t('Demo-Termin auswählen','Choose demo appointment'),'appointment','secondary')}</div></section>`}
function services(){return heading(t('Rund um deinen Bildungsweg','Along your learning journey'),t('Gut vorbereitet. Gut angekommen.','Well prepared. Ready to settle in.'),t('Sprachlernen, Prüfungen und Wohnen als zusammenhängende Themen — mit klar getrennten Anfragen und Entscheidungen.','Language learning, exams and housing as connected topics — with separate requests and decisions.'))+`<section class="section"><div class="info-grid">${panel(t('Prüfungen & Vorbereitung','Exams & preparation'),`<p>${t('ÖSD, TestDaF und digitaler TestAS gehören zum beschriebenen Angebotsrahmen. Anbieterregeln, Termine und Kapazitäten müssen jeweils bestätigt werden.','ÖSD, TestDaF and digital TestAS are part of the described service scope. Provider rules, dates and capacity must be confirmed separately.')}</p>${button(t('Prüfungsweg ansehen','Explore exam pathway'),'exam','secondary')}`)}${panel(t('Wohnen & Ankommen','Housing & arrival'),`<p>${t('Eine Anfrage sammelt deinen Bedarf. Verfügbarkeit, Angebot und Mietvertrag sind eigene Schritte — es wird kein Zimmer automatisch reserviert.','An enquiry captures your needs. Availability, an offer and a rental agreement are separate steps — no room is automatically reserved.')}</p>${button(t('Wohnanfrage simulieren','Simulate housing enquiry'),'housing','secondary')}`)}${panel(t('Hochschulbewerbung','University application'),`<p>${t('Vorbereitung und Bewerbungsunterstützung lassen sich gemeinsam planen. Die Entscheidung über den Studienplatz bleibt bei der jeweiligen Hochschule.','Preparation and application support can be planned together. The university makes the final decision on admission.')}</p>${button(t('Beratung vorbereiten','Prepare advisory brief'),'brief','secondary')}`)}${panel(t('Deutsch A1 bis C1','German A1 to C1'),`<p>${t('Sprachkenntnisse entwickeln und einen sinnvollen Einstieg klären. Der passende Kurs wird anhand des tatsächlichen Sprachstands besprochen.','Develop your language skills and find a suitable starting point. The right programme is discussed based on your actual language level.')}</p>${link(t('Sprachkurse ansehen','Explore language courses'),'/course/Deutsch','secondary')}`)}</div></section>`}
const roleLabels=()=>({applicant:t('Bewerber:in','Applicant'),student:t('Teilnehmer:in','Student'),teacher:t('Lehrkraft','Teacher'),admin:t('Zulassungsbüro','Admissions'),partner:t('Agentur','Agency')});
function portal(role,view='overview'){if(!roleLabels()[role])role='applicant';state.role=role;const labels=roleLabels();const nav=role==='teacher'? [['overview',t('Mein Unterricht','My teaching')],['attendance',t('Anwesenheit','Attendance')],['grades',t('Bewertung','Assessment')],['documents',t('Materialien','Materials')]]:role==='admin'?[['overview',t('Arbeitsübersicht','Work overview')],['cases',t('Bewerbungen','Applications')],['documents',t('Unterlagen','Documents')],['messages',t('Kommunikation','Messages')]]:role==='partner'?[['overview',t('Meine Kandidaten','My candidates')],['financials',t('Provisionen','Commissions')]]:[['overview',t('Mein Weg','My journey')],['tasks',t('Aufgaben','Tasks')],['documents',t('Dokumente','Documents')],['messages',t('Nachrichten','Messages')],['financials',t('Vertrag & Finanzen','Contract & finance')],['appointments',t('Termine','Appointments')]];if(!nav.some(([key])=>key===view))view='overview';return `<div class="portal-top"><div><strong>${t('Mein Studienkolleg','My Studienkolleg')}</strong><small>${t('Rollenansicht · Fiktive Demodaten · Keine Anmeldung','Role preview · Fictional sample data · No authentication')}</small></div><label><span class="skip">${t('Rolle wechseln','Switch role')}</span><select id="role-select">${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${k===role?'selected':''}>${v}</option>`).join('')}</select></label></div><nav class="portal-nav" aria-label="Portal">${nav.map(([k,v])=>`<a href="#/portal/${role}/${k}" class="${view===k?'active':''}">${v}</a>`).join('')}</nav><div class="dashboard">${portalContent(role,view)}</div>`}
function portalContent(role,view){if(view==='documents'&&role==='teacher')return `<h1>${t('Materialien für deinen Unterricht.','Materials for your teaching.')}</h1><p class="intro">${t('Zugeordnete Kurse · Nur fiktive Unterrichtsmaterialien.','Assigned classes · Fictional teaching materials only.')}</p>${panel(t('T-01 · Materialmappe','T-01 · Teaching folder'),`<div class="file-row"><div class="file-main"><span class="file-icon">T</span><div><strong>${t('Mathematik · Übungsblatt 01','Mathematics · Practice sheet 01')}</strong><small>${t('Unterrichtsmaterial · Demo','Teaching material · Demo')}</small></div></div>${button(t('Vorschau','Preview'),'lms','small secondary')}</div><div class="actions">${button(t('Klassenbuch-Entwurf','Classbook draft'),'classbook','secondary')}</div>`)}`;if(view==='documents')return `<h1>${t('Alles an einem Ort.','Everything in one place.')}</h1><p class="intro">${t('Nur Musterdateien. Kein Zugriff auf echte Akten.','Sample files only. No access to real records.')}</p>${panel(t('Dokumentenmappe','Document folder'),documentRows(role==='applicant'||role==='admin'))}`;
if(view==='messages'&&role==='applicant')return `<h1>${t('Deine Nachrichten','Your messages')}</h1><p class="intro">${t('Lokale Vorschau · keine eingegangene Nachricht und kein Versand.','Local preview · no received message and no sending.')}</p>${panel(t('Aktueller Musterstatus','Current sample status'),`<p>${t('Dieser Hinweis folgt deinen Musterunterlagen. Er ist keine Rückmeldung des Zulassungsbüros.','This notice reflects your sample documents. It is not a response from admissions.')}</p>${applicantDocumentStatus()}<p>${t('Die persönliche Prüfung bleibt offen. Es wurde nichts eingereicht.','Personal review remains pending. Nothing was submitted.')}</p><label class="field">${t('Demo-Antwort','Demo reply')}<textarea id="demo-message" placeholder="${t('Nur fiktive Inhalte …','Fictional details only …')}"></textarea></label>${button(t('Antwort simulieren','Simulate reply'),'message')}`)}`;
if(view==='messages')return `<h1>${t('Deine Nachrichten','Your messages')}</h1><p class="intro">${t('Beispielverlauf · Nachrichten werden nicht versendet.','Sample conversation · Messages are not sent.')}</p>${panel(t('Zulassungsberatung','Admissions guidance'),`<div class="notice"><b>${t('Studienkolleg · Demobeispiel','Studienkolleg · Demo sample')}</b><p style="margin:8px 0 0">${t('Bitte ergänze die Muster-Notenübersicht. Danach kann die fachliche Prüfung fortgesetzt werden.','Please add the sample transcript. The eligibility review can then continue.')}</p></div><label class="field">${t('Demo-Antwort','Demo reply')}<textarea id="demo-message" placeholder="${t('Nur fiktive Inhalte …','Fictional details only …')}"></textarea></label>${button(t('Antwort simulieren','Simulate reply'),'message')}`)}`;
if(view==='appointments')return `<h1>${t('Zeit für deine Fragen.','Time for your questions.')}</h1><p class="intro">${t('Fiktive Terminübersicht — keine Live-Verfügbarkeit.','Fictional schedule — not live availability.')}</p>${panel(t('Beratung','Guidance'),`<div class="schedule"><time>10:00</time><div><b>${t('Kurswahl & nächste Schritte','Programme choice & next steps')}</b><small>${t('Beispieltermin · Dienstag · Online','Sample appointment · Tuesday · Online')}</small></div>${button(t('Details','Details'),'appointment','small secondary')}</div>`)}`;
if(view==='financials')return `<h1>${role==='partner'?t('Provisionen im Überblick','Commission overview'):t('Getrennte Schritte. Klarer Status.','Separate steps. Clear status.')}</h1><p class="intro">${t('Keine echten Beträge, Rechnungen oder Zahlungsvorgänge.','No actual amounts, invoices or payment transactions.')}</p>${role==='partner'?panel(t('Provisionsfall · Demo','Commission case · Demo'),`<p>${t('Kandidat DEMO-002 · Status: Prüfung offen. Provisionsberechtigung und tatsächliche Zahlung bleiben getrennt.','Candidate DEMO-002 · Status: review pending. Commission eligibility and actual payment remain separate.')}</p>${badge(t('Keine Freigabe','Not approved'))}`):panel(t('Vertrags- und Freigabestatus','Contract and approval status'),`<div class="task-row"><strong>${t('Fachliche Eignung','Academic eligibility')}</strong>${badge(t('Prüfung offen','Review pending'))}</div><div class="task-row"><strong>${t('Vertrag','Contract')}</strong>${badge(t('Musterentwurf','Sample draft'),'blue')}</div><div class="task-row"><strong>${t('Zahlungseingang','Payment received')}</strong>${badge(t('Nicht bestätigt','Not confirmed'))}</div><div class="task-row"><strong>${t('Lernzugang','Learning access')}</strong>${badge(t('Gesonderte Freigabe','Separate approval'))}</div><div class="actions">${button(t('Mustervertrag ansehen','View sample contract'),'contract','secondary')}</div>${notice(t('Ein unterschriebener Vertrag ersetzt keinen bestätigten Zahlungseingang oder freigegebenen Lernzugang.','A signed contract does not replace a confirmed payment or approved learning access.'))}`)}`;
if(role==='teacher')return teacher(view);if(role==='admin')return admin(view);if(role==='partner')return `<h1>${t('Zugeordnete Kandidaten.','Assigned candidates.')}</h1><p class="intro">${t('Agenturansicht · Nur zugeordnete Vorgänge, keine Bewerberdokumente oder internen Notizen.','Agency view · Assigned cases only, no applicant documents or internal notes.')}</p>${panel(t('Meine Kandidaten · Demo','My candidates · Demo'),`<div class="task-row"><div><strong>DEMO-001</strong><small>T-Kurs</small></div>${badge(t('Unterlagenprüfung','Document review'),'blue')}</div><div class="task-row"><div><strong>DEMO-002</strong><small>Deutsch B2</small></div>${badge(t('Beratung offen','Guidance pending'))}</div>`)}`;
if(view==='tasks')return `<h1>${t('Dein nächster kleiner Schritt.','Your next small step.')}</h1><p class="intro">${t('Alle Aufgaben sind fiktive Beispiele.','All tasks are fictional examples.')}</p>${panel(t('Offene Aufgaben','Open tasks'),taskRows(role))}`;
if(role==='student')return `<span class="eyebrow">${t('Teilnehmerportal · Demo','Student portal · Demo')}</span><h1>${t('Guten Morgen, Alex.','Good morning, Alex.')}</h1><p class="intro">${t('Dein Lerntag, deine Unterlagen, dein nächster Schritt.','Your learning day, your documents, your next step.')}</p><div class="stat-grid">${stat(t('Nächster Unterricht','Next class'),'09:00')}${stat(t('Aufgaben · Beispiel','Tasks · sample'),'2')}${stat(t('Mein Kurs · Beispiel','My class · sample'),'T-01')}</div><div class="info-grid">${panel(t('Dein Lerntag · Beispieldaten','Your learning day · sample data'),`<div class="schedule"><time>09:00</time><div><b>${t('Mathematik','Mathematics')}</b><small>T-01 · ${t('Raum 2 · Demo','Room 2 · Demo')}</small></div></div><div class="schedule"><time>11:00</time><div><b>${t('Deutsch','German')}</b><small>${t('Textverständnis · Demo','Reading comprehension · Demo')}</small></div></div><div class="actions">${button(t('OpenOLAT-Vorschau','OpenOLAT preview'),'lms','secondary')}</div>`)}${panel(t('Deine nächsten Schritte','Your next steps'),taskRows('student'))}${panel(t('Ankommen & Alltag','Arrival & everyday life'),`<p>${t('Behalte Visum-Nachweise, deine Ankunft und offene Wohnfragen im Blick. Selbstauskünfte sind noch keine intern bestätigten Nachweise.','Keep track of visa evidence, arrival and housing questions. Self-reported information is not yet internally verified.')}</p><div class="actions">${button(t('Ankunftscheck öffnen','Open arrival checklist'),'arrival','secondary')}${button(t('Wohnanfrage','Housing enquiry'),'housing','secondary')}</div>`,'wide')}</div>`;
return `<span class="eyebrow">${t('Bewerberportal · Demo','Applicant portal · Demo')}</span><h1>${t('Dein Weg nimmt Form an.','Your path is taking shape.')}</h1><p class="intro">${t('Willkommen, Alex Beispiel. Hier laufen deine nächsten Schritte zusammen.','Welcome, Alex Sample. This is where your next steps come together.')}</p><div class="panel"><div class="section-head"><h3 style="margin:0">${t('Deine Bewerbung · DEMO-001','Your application · DEMO-001')}</h3>${badge(t('Unterlagen ergänzen','Add documents'),'blue')}</div><div class="progress"><span style="width:35%"></span></div><p class="subtle">${t('Orientierung → Unterlagen → Persönliche Prüfung → Angebot','Orientation → Documents → Personal review → Offer')}</p><p>${t('Die Muster-Notenübersicht fehlt noch. Ergänze sie, damit du den nächsten Schritt im Pilot kennenlernen kannst.','The sample transcript is still missing. Add it to explore the next step in the pilot.')}</p>${link(t('Unterlagen öffnen','Open documents'),'/portal/applicant/documents')}</div><div class="info-grid" style="margin-top:18px">${panel(t('Deine nächsten Schritte','Your next steps'),taskRows('applicant'))}${panel(t('Deine Beratung','Your guidance'),`<div class="empty-icon">☏</div><p>${t('Fragen zum Bildungsweg? Bereite einen kurzen Beratungsbrief vor oder sieh dir die Demo-Terminwahl an.','Questions about your pathway? Prepare a short advisory brief or explore the demo appointment selector.')}</p>${button(t('Termin auswählen','Choose appointment'),'appointment','secondary')}`)}</div>`}
const stat=(label,value)=>`<div class="stat"><strong>${value}</strong><small>${label}</small></div>`;
function missingApplicantDocuments(){return [0,1,2].filter(i=>!state.uploads[i])}
function applicantDocumentStatus(){const missing=missingApplicantDocuments();return missing.length?`<p>${t('Noch offene Musterunterlagen','Missing sample documents')}: ${missing.map(i=>esc(docNames()[i])).join(', ')}.</p>`:`<p>${t('Alle drei Musterunterlagen sind vorhanden · Prüfung offen.','All three sample documents are present · review pending.')}</p>`}
function taskRows(role){if(role==='applicant'){const missing=missingApplicantDocuments();return applicantDocumentStatus()+missing.map(i=>`<div class="task-row"><div><strong>${esc(docNames()[i])}</strong><small>${t('Muster ergänzen · kein echter Upload','Add sample · no real upload')}</small></div>${button(t('Muster hinzufügen','Add sample'),'upload','small secondary',`data-value="${i}"`)}</div>`).join('')+`<div class="task-row"><div><strong>${t('Beratung vorbereiten','Prepare advisory brief')}</strong><small>${t('Persönliche Prüfung offen · keine Zulassung','Personal review pending · no admission')}</small></div>${button(t('Öffnen','Open'),'brief','small secondary')}</div>`}const tasks=role==='student'?[[t('Mathematik: Übungsblatt','Mathematics: practice sheet'),'lms'],[t('Ankunftsangaben prüfen','Review arrival details'),'arrival']]:[[t('Muster-Notenübersicht ergänzen','Add sample transcript'),'upload'],[t('Beratung vorbereiten','Prepare advisory brief'),'brief']];return tasks.map(([label,action],i)=>`<div class="task-row"><div><strong>${label}</strong><small>${t('Demo-Aufgabe · kein echter Vorgang','Demo task · no actual case')}</small></div>${button(t('Öffnen','Open'),action,'small secondary',`data-value="1"`)}</div>`).join('')}
function teacher(view){if(view==='attendance')return `<h1>${t('Anwesenheit erfassen.','Record attendance.')}</h1><p class="intro">T-01 · ${t('Mathematik · fiktive Unterrichtseinheit','Mathematics · fictional lesson')}</p>${panel(t('Zugeordneter Kurs · Demo','Assigned class · Demo'),['Alex Beispiel','Sam Beispiel','Kim Beispiel'].map((n,i)=>`<label class="attendance">${n}<select data-attendance="${i}">${['Anwesend','Abwesend','Entschuldigt'].map(v=>`<option ${state.attendance[i]===v?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')+`<div class="actions">${button(t('Demo-Erfassung bestätigen','Confirm demo record'),'attendance-save')}</div>`)}`;if(view==='grades')return `<h1>${t('Entwurf bleibt Entwurf.','A draft stays a draft.')}</h1><p class="intro">${t('Beispiel einer Leistungsbewertung. Keine echten Noten oder Zeugnisse.','Example of an assessment. No real grades or certificates.')}</p>${panel(t('T-01 · Mathematik','T-01 · Mathematics'),`<div class="task-row"><strong>Alex Beispiel</strong>${badge(t('Entwurf · nicht veröffentlicht','Draft · unpublished'),'blue')}</div><label class="field" style="margin-top:20px">${t('Fiktive Bewertung','Fictional assessment')}<select><option>${t('Noch nicht bewertet','Not assessed')}</option><option>${t('Beispiel: gut','Example: good')}</option><option>${t('Beispiel: befriedigend','Example: satisfactory')}</option></select></label>${button(t('Freigabeprozess ansehen','View approval process'),'grade','secondary')}`)}`;return `<span class="eyebrow">${t('Lehrkräfteportal · Demo','Teacher portal · Demo')}</span><h1>${t('Raum für guten Unterricht.','Space for good teaching.')}</h1><p class="intro">${t('Nur zugeordnete Kurse. Unterricht, Anwesenheit und Materialien zusammen im Blick.','Assigned classes only. Teaching, attendance and materials at a glance.')}</p><div class="stat-grid">${stat(t('Kurse · Beispiel','Classes · sample'),'2')}${stat(t('Heute · Beispiel','Today · sample'),'3 UE')}${stat(t('Entwürfe · Beispiel','Drafts · sample'),'1')}</div>${panel(t('Nächste Unterrichtseinheit','Next lesson'),`<div class="schedule"><time>09:00</time><div><b>T-01 · ${t('Mathematik','Mathematics')}</b><small>${t('Fiktiver Stundenplan · Raum 2','Fictional timetable · Room 2')}</small></div>${link(t('Anwesenheit','Attendance'),'/portal/teacher/attendance','small secondary')}</div><div class="actions">${button(t('Klassenbuch öffnen','Open classbook'),'classbook','secondary')}${link(t('Bewertungsentwurf','Assessment draft'),'/portal/teacher/grades','secondary')}</div>`)}`}
const admissionsCases={new:['DEMO-003','DEMO-004'],missing:['DEMO-001','DEMO-005'],review:['DEMO-002']};
function admin(view){return `<span class="eyebrow">${t('Zulassungsbüro · Demo','Admissions office · Demo')}</span><h1>${t('Prüfen. Einordnen. Begleiten.','Review. Understand. Guide.')}</h1><p class="intro">${t('Fiktive Arbeitsliste. Fachliche Entscheidungen und Freigaben bleiben bei Menschen.','Fictional work queue. Eligibility decisions and approvals remain with people.')}</p><div class="stat-grid">${stat(t('Neue Fälle · Demo','New cases · demo'),admissionsCases.new.length)}${stat(t('Nachforderung · Demo','Awaiting documents · demo'),admissionsCases.missing.length)}${stat(t('Zur Prüfung · Demo','Ready for review · demo'),admissionsCases.review.length)}</div><div class="kanban">${[[t('Neu eingegangen','New'),admissionsCases.new],[t('Unterlagen ergänzen','Awaiting documents'),admissionsCases.missing],[t('Fachliche Prüfung','Eligibility review'),admissionsCases.review]].map(([title,ids])=>`<section class="kanban-column"><h3>${title} <span style="float:right">${ids.length}</span></h3>${ids.map((id,i)=>`<button class="case-card" data-action="case" data-value="${id}"><b>${id}</b><small>${i?'Deutsch B2':'T-Kurs'} · ${t('Fiktiver Vorgang','Fictional case')}</small>${badge(t('Fall öffnen','Open case'),'blue')}</button>`).join('')}</section>`).join('')}</div>${notice(t('Keine automatischen Zulassungen. Vertrag, Zahlung, Semesterfreigabe und technischer Zugang sind getrennte Prüfschritte.','No automatic admission. Contract, payment, semester approval and technical access are separate review steps.'))}`}
const personaMemory={};let currentPersona='journey';
function syncPersona(r){const role=r.startsWith('/portal/')?r.split('/')[2]:'applicant';const next=['applicant','student'].includes(role)?'journey':role;if(next!==currentPersona){personaMemory[currentPersona]={brief:state.brief,chat:state.chat};const saved=personaMemory[next]||{brief:'',chat:[]};state.brief=saved.brief;state.chat=saved.chat;currentPersona=next;}}
function rolePrompts(){if(state.role==='teacher')return [[t('Anwesenheit dokumentieren','Record attendance'),'attendance'],[t('Entwurf oder veröffentlichte Note?','Draft or published grade?'),'grades'],[t('Unterricht vorbereiten','Prepare teaching'),'teaching']];if(state.role==='admin')return [[t('Prüfschritte im Aufnahmeprozess','Admissions review steps'),'status'],[t('Wie funktionieren Nachforderungen?','How do document requests work?'),'review'],[t('Workflow-Baustein erklären','Explain workflow component'),'workflow']];if(state.role==='partner')return [[t('Welche Kandidaten sehe ich?','Which candidates can I see?'),'agency'],[t('Wann ist eine Provision freigegeben?','When is a commission approved?'),'commission'],[t('Was bedeutet dieser Status?','What does this status mean?'),'status']];if(state.role==='student')return [[t('Wie komme ich zu meinen Lerninhalten?','How do I access learning content?'),'learning'],[t('Meine Ankunft vorbereiten','Prepare my arrival'),'arrival'],[t('Was bedeutet dieser Status?','What does this status mean?'),'status']];return [[t('Was bedeutet dieser Status?','What does this status mean?'),'status'],[t('Welche Unterlagen fehlen?','Which documents are missing?'),'documents'],[t('An Beratung übergeben','Prepare human handoff'),'handoff']];}
function assistant(){const r=route();const isPortal=r.startsWith('/portal');let title=isPortal?t('Dein nächster Schritt.','Your next step.'):t('Lass uns deinen Weg finden.','Let’s find your path.');let intro=r.startsWith('/apply')?t('Ich helfe dir, den Demo-Entwurf zu strukturieren. Bitte keine echten persönlichen Angaben eingeben.','I can help structure your demo draft. Please do not enter real personal details.'):isPortal?t('Ich erkläre die gezeigten Demo-Aufgaben und Status. Entscheidungen bleiben bei der zuständigen Fachrolle.','I explain the demo tasks and status. Decisions remain with the authorised staff.'):t('Du hast ein Ziel, aber noch Fragen? Wir sortieren Kurswahl, Voraussetzungen und den nächsten Schritt.','You have a goal, but still have questions? Let’s organise programme choices, requirements and next steps.');return `<aside class="assistant" aria-label="${t('Demo-Studienbegleiter','Demo study companion')}"><div class="assistant-head"><div class="assistant-symbol">${arrow}</div><div><b>${t('Dein Studienbegleiter','Your study companion')}</b><small>${t('Orientierung · Kontext · Nächster Schritt','Guidance · Context · Next step')}</small></div><button class="mobile-close" style="display:none" data-action="close-assistant" aria-label="Close">×</button></div><div class="assistant-body"><span class="eyebrow">${t('Gemeinsam weiterdenken','Find your next step')}</span><h2>${title}</h2><p class="assistant-intro">${intro}</p><div>${(isPortal?rolePrompts():[[t('Welcher Kurs passt zu mir?','Which programme fits me?'),'course'],[t('Was brauche ich zur Bewerbung?','What do I need to apply?'),'documents'],[t('Ich möchte Deutsch lernen','I want to learn German'),'german']]).map(([label,value])=>`<button class="suggestion" data-action="chat-prompt" data-value="${value}">${label}${arrow}</button>`).join('')}</div><span class="context-chip">${t('Kontext','Context')}: ${esc(contextName())}</span><div id="chat-log" aria-live="polite">${state.chat.map(m=>`<div class="chat-bubble ${m.role}"><small>${m.role==='user'?t('DU','YOU'):t('DEMO-BEGLEITER','DEMO COMPANION')}</small>${esc(m.text)}</div>`).join('')}</div><div class="brief-box"><b>${currentPersona==='journey'?t('Dein Beratungsbrief','Your advisory brief'):t('Deine Arbeitsnotiz · Demo','Your work note · Demo')}</b><p>${state.brief?esc(state.brief.slice(0,180)):(currentPersona==='journey'?t('Kursinteresse, offene Fragen und nächste Schritte — an einem Ort.','Programme interests, questions and next steps — in one place.'):t('Rollenbezogene Fragen und nächste Schritte. Getrennt vom Bewerberentwurf.','Role-specific questions and next steps. Separate from the applicant draft.'))}</p><button data-action="brief">${state.brief?t('Brief bearbeiten →','Edit brief →'):t('Gemeinsam vorbereiten →','Prepare together →')}</button></div></div><form class="assistant-compose" id="chat-form"><label class="skip" for="chat-input">${t('Deine Frage','Your question')}</label><textarea id="chat-input" placeholder="${t('Deine Frage — bitte nur fiktive Angaben …','Your question — fictional details only …')}" maxlength="600"></textarea><button class="btn" type="submit">${t('Nächsten Schritt finden','Find the next step')} ${arrow}</button><small>${t('Regelbasierte Demo, keine Live-KI. Keine Übermittlung. Keine Zulassungs-, Visa- oder Rechtsberatung. Quellen: Workflow 22.10.2026 / Website-Abruf 30.10.2026.','Rule-based demo, not live AI. No transmission. No admission, visa or legal advice. Sources: workflow 22 Oct 2026 / website reviewed 30 Oct 2026.')}</small></form></aside>`}
function contextName(){const r=route();if(r.startsWith('/portal'))return roleLabels()[state.role];if(r.startsWith('/course/'))return t('Kursdetails','Programme details');if(r.startsWith('/courses'))return t('Kursauswahl','Programme finder');if(r.startsWith('/apply'))return t('Bewerbung vorbereiten','Prepare application');if(r.startsWith('/admission'))return t('Aufnahme & Voraussetzungen','Admission & requirements');return t('Orientierung','Orientation')}
function footer(){return `<footer class="footer"><div><b>STUDIENKOLLEG AACHEN</b><br>${t('Konzeptpilot von NeXify · Kein Produktivsystem','Concept pilot by NeXify · Not a production system')}</div><div class="footer-links"><a href="#/courses">${t('Kurse','Programmes')}</a><a href="#/services">${t('Angebote','Services')}</a><a href="#/help">${t('Hilfe','Help')}</a><a href="#/about">${t('Pilot & Quellen','Pilot & sources')}</a><button class="lang" data-action="privacy">${t('Datenschutz im Pilot','Pilot privacy')}</button></div></footer>`}
function about(){return heading(t('Transparenz im Pilot','Pilot transparency'),t('Ein Konzept. Keine Live-Plattform.','A concept. Not a live platform.'),t('Dieser klickbare Pilot zeigt eine mögliche neue Website und rollenbezogene Portale. Funktionen und Daten sind demonstrativ.','This clickable pilot demonstrates a possible new website and role-based portals. Features and data are illustrative.'))+`<section class="section">${panel(t('Quellen & Einordnung','Sources & context'),`<ul><li>${t('Markenreferenz: öffentlich erreichbare Website deinstudienkolleg.de, Abruf 30.10.2026.','Brand reference: publicly accessible deinstudienkolleg.de, reviewed 30 Oct 2026.')}</li><li>${t('Die vom Auftraggeber genannte Domain meinstudienkolleg.de war beim Abruf nicht erreichbar (503). Sie wurde nicht stillschweigend als identische Domain behandelt.','The requested domain meinstudienkolleg.de was unavailable (503). It was not silently treated as the same domain.')}</li><li>${t('Fachlicher Rahmen: bereitgestellte W2G-Prozesse vom 22.10.2026, Workflow-Broschüre 30.10.2026. Beschriebene Sollprozesse, kein Nachweis einer Implementierung.','Business context: supplied W2G processes dated 22 Oct 2026 and workflow brochure dated 30 Oct 2026. Target processes, not evidence of implementation.')}</li><li>${t('NeXify-Layoutprinzip: Information links, kontextbezogene Assistenz rechts. Wiederverwendbare Komponenten und zentrale Design-Tokens.','NeXify layout principle: information on the left, contextual assistance on the right. Reusable components and central design tokens.')}</li></ul>${notice(t('Kein Login, keine Berechtigungsprüfung, kein echtes Backend, kein Upload, kein Versand, keine Zahlung. Rollenwechsel simuliert ausschließlich die Darstellung.','No login, authorisation enforcement, backend, upload, submission or payment. Switching roles only simulates the interface.'))}`)}</section>`}
function render(){const r=route().split('?')[0];syncPersona(r);let body;if(r==='/')body=home();else if(r==='/courses')body=courseList();else if(r.startsWith('/course/'))body=courseDetail(r.split('/')[2]);else if(r==='/admission')body=admission();else if(r==='/apply')body=application();else if(r.startsWith('/portal/'))body=portal(r.split('/')[2],r.split('/')[3]||'overview');else if(r==='/help')body=help();else if(r.startsWith('/services'))body=services();else body=about();document.documentElement.lang=state.lang;const skip=document.querySelector('body > .skip');if(skip)skip.textContent=t('Zum Inhalt','Skip to content');document.getElementById('app').innerHTML=header()+`<div class="layout"><main id="main" class="page">${body}${footer()}</main>${assistant()}</div><button class="mobile-assistant" data-action="open-assistant">✳ ${t('Studienbegleiter','Study companion')}</button>`;bind();}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),4500)}
let focusBeforeModal;
function modal(title,content,actions=''){focusBeforeModal=document.activeElement;document.getElementById('overlay').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${title}</h2><button class="close" data-action="close-modal" aria-label="${t('Schließen','Close')}">×</button></div>${content}<div class="actions">${actions||button(t('Verstanden','Understood'),'close-modal','secondary')}</div></section></div>`;bind(document.getElementById('overlay'));document.querySelector('.modal button, .modal input, .modal textarea')?.focus()}
function closeModal(){document.getElementById('overlay').innerHTML='';focusBeforeModal?.focus()}
function chat(value,text){const responses={attendance:t('Öffne die Anwesenheitsansicht für den zugeordneten Kurs. Die Erfassung bleibt im Pilot lokal; Korrekturen und echte Klassenbucheinträge benötigen den freigegebenen Prozess.','Open attendance for your assigned class. Records remain local in this pilot; corrections and real classbook entries require the approved process.'),grades:t('Ein Bewertungsentwurf ist nicht veröffentlicht. Öffne Bewertung, um den vorgesehenen Freigabeprozess anzusehen.','An assessment draft is not published. Open Assessment to view the planned approval process.'),teaching:t('Unter Mein Unterricht findest du den Beispielstundenplan und das Klassenbuch. Es werden keine Inhalte an echte Teilnehmende verteilt.','My teaching shows the sample timetable and classbook. No content is distributed to real students.'),review:t('Öffne eine Demo-Bewerbung und erfasse eine fiktive Begründung. Eine Nachforderung kann simuliert werden; es wird keine Nachricht versendet.','Open a demo application and enter a fictional reason. A document request can be simulated; no message is sent.'),workflow:t('Der Workflow-Builder zeigt Dokumentenagent, Aufnahmeagent und verpflichtende menschliche Entscheidung. Die Fachagenten sind geplant, nicht aktiv.','The workflow builder shows a document agent, admissions agent and mandatory human decision. Specialist agents are planned, not active.'),agency:t('Die Agenturansicht zeigt ausschließlich zugeordnete Demo-Kandidaten und Status. Bewerberdokumente und interne Notizen gehören nicht in diese Ansicht.','The agency view shows assigned demo candidates and status only. Applicant documents and internal notes do not belong in this view.'),commission:t('Provisionsberechtigung, Freigabe und tatsächliche Auszahlung sind getrennte Schritte. Dieser Pilot zeigt keine echten Beträge oder Zahlungen.','Commission eligibility, approval and actual payment are separate steps. This pilot shows no real amounts or payments.'),learning:t('Öffne im Teilnehmerportal die OpenOLAT-Vorschau. Der spätere Lernzugang setzt eine gesonderte technische Freigabe voraus. Dieser Pilot ist nicht mit dem LMS verbunden.','Open the OpenOLAT preview in the student portal. Future learning access requires separate technical approval. This pilot is not connected to the LMS.'),arrival:t('Der Ankunftscheck hilft, Fragen zu Einreise, Nachweisen und Unterkunft zusammenzustellen. Er ersetzt weder behördliche Entscheidungen noch eine Zimmerreservierung.','The arrival checklist helps organise questions about entry, evidence and housing. It replaces neither official decisions nor a room reservation.'),course:t('Dein Wunschstudium ist der Ausgangspunkt: T für Technik/Naturwissenschaft, M für Medizin/Biologie, W für Wirtschaft, G für Geisteswissenschaften. Das ist Orientierung, keine Zulassung. Öffne die Kursübersicht und bereite danach einen Beratungsbrief vor.','Your intended degree is the starting point: T for engineering/science, M for medicine/biology, W for business, G for humanities. This is orientation, not admission. Explore programmes, then prepare an advisory brief.'),documents:t('Für die Orientierung sind Abschlusszeugnis, Notenübersicht und vorhandene Sprachnachweise hilfreich. Die Zulassungsberatung bestätigt die individuelle Liste. Im Pilot kannst du ausschließlich Musterdateien hinzufügen.','School certificates, transcripts and existing language certificates are useful for orientation. Admissions staff confirm the individual list. In this pilot you can add sample files only.'),german:t('Der beschriebene Sprachbereich umfasst A1 bis C1. Ein passender Einstieg hängt vom geprüften Sprachstand ab. Schau dir „Deutsch lernen“ an und notiere deinen Beratungsbedarf.','The described language range covers A1 to C1. A suitable starting point depends on your assessed language level. Explore “Learn German” and note your advisory needs.'),status:t('Dieser Status ist ein Beispiel, keine echte Entscheidung. Fachliche Eignung, Vertrag, Zahlung und Lernzugang sind getrennt. Die zuständige Fachrolle muss jeden erforderlichen Schritt ausdrücklich prüfen.','This status is an example, not a real decision. Eligibility, contract, payment and learning access are separate. Authorised staff must explicitly review each required step.'),handoff:t('Du kannst deinen Beratungsbrief bearbeiten und offene Fragen zusammenfassen. Eine echte Übergabe an die Beratung ist hier nicht angeschlossen — der Brief bleibt nur in dieser geöffneten Demo.','You can edit your advisory brief and summarise open questions. No real handoff is connected — the brief stays within this open demo.'),default:t('Ich bin eine regelbasierte Demo und kann diese Frage nicht individuell prüfen. Für eine verbindliche Antwort bereite bitte einen Beratungsbrief vor. Kurswahl, Unterlagen und Status kann ich beispielhaft erklären.','I am a rule-based demo and cannot assess this question individually. For a binding answer, prepare an advisory brief. I can illustrate programme choices, documents and status.')};state.chat.push({role:'user',text:text||rolePrompts().find(p=>p[1]===value)?.[0]||({course:t('Welcher Kurs passt zu mir?','Which programme fits me?'),documents:t('Welche Unterlagen brauche ich?','Which documents do I need?'),german:t('Ich möchte Deutsch lernen.','I want to learn German.'),status:t('Was bedeutet dieser Status?','What does this status mean?'),handoff:t('Wie erreiche ich die Beratung?','How do I reach an adviser?')}[value])});state.chat.push({role:'assistant',text:responses[value]||responses.default});state.chat=state.chat.slice(-8);const wasOpen=document.querySelector('.assistant')?.classList.contains('open');render();if(wasOpen)document.querySelector('.assistant').classList.add('open');document.querySelector('.assistant-body').scrollTop=document.querySelector('.assistant-body').scrollHeight}
function bind(root=document){root.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>action(el.dataset.action,el.dataset.value)));root.querySelectorAll('[data-field]').forEach(el=>el.addEventListener('input',()=>{if(el.dataset.field==='brief')state.brief=el.value;else state.application[el.dataset.field]=el.value}));root.querySelectorAll('[data-attendance]').forEach(el=>el.addEventListener('change',()=>state.attendance[el.dataset.attendance]=el.value));root.querySelector('#role-select')?.addEventListener('change',e=>location.hash='/portal/'+e.target.value);root.querySelector('#chat-form')?.addEventListener('submit',e=>{e.preventDefault();const input=document.getElementById('chat-input');const val=input.value.trim();if(!val)return;const s=val.toLowerCase();chat(/deutsch|german|sprach/.test(s)?'german':/unterlag|dokument|document|zeugnis/.test(s)?'documents':/kurs|course|programme|studier/.test(s)?'course':/status|zahlung|payment/.test(s)?'status':/berat|advis|human/.test(s)?'handoff':'default',val)})}
function action(a,v){if(a==='course-brief'){state.brief=t(...courseGuidance[v][2]);action('brief');return}else if(a==='language'){state.lang=state.lang==='de'?'en':'de';render()}else if(a==='filter'){state.tab=v;render()}else if(a==='step'){state.step=Number(v);render()}else if(a==='next'||a==='back'){state.step+=a==='next'?1:-1;render()}else if(a==='complete'){state.submitted=true;render();window.scrollTo(0,0)}else if(a==='edit-application'){state.submitted=false;state.step=0;render()}else if(a==='topic'){state.brief=t('Ich möchte besprechen: ','I would like to discuss: ')+v;render()}else if(a==='upload'){state.uploads[v||0]=true;render();toast(t('Musterdatei ergänzt — kein echter Upload.','Sample file added — no real upload.'))}else if(a==='chat-prompt')chat(v);else if(a==='open-assistant')document.querySelector('.assistant').classList.add('open');else if(a==='close-assistant')document.querySelector('.assistant').classList.remove('open');else if(a==='close-modal')closeModal();else if(a==='brief'){modal(currentPersona==='journey'?t('Dein Beratungsbrief','Your advisory brief'):t('Deine Arbeitsnotiz · Demo','Your work note · Demo'),`<p>${t('Nur fiktive Angaben. Dieser Brief wird nicht versendet und beim Neuladen verworfen.','Fictional details only. This brief is not sent and is discarded when you reload.')}</p><label class="field">${t('Kursinteresse, Fragen, nächster Schritt','Programme interest, questions, next step')}<textarea id="brief-edit" maxlength="1500">${esc(state.brief||(currentPersona!=='journey'?t('Meine Aufgabe: '+roleLabels()[state.role]+'\nMein nächster Schritt: ','My task: '+roleLabels()[state.role]+'\nMy next step: '):t('Mein Interesse: '+state.application.course+'\nMeine Frage: Welcher nächste Schritt passt zu meinem Bildungsziel?','My interest: '+state.application.course+'\nMy question: What is the next step for my study goal?')))}</textarea></label>`,button(t('Demo-Brief übernehmen','Use demo brief'),'save-brief'))}else if(a==='save-brief'){state.brief=document.getElementById('brief-edit').value;closeModal();render();toast(t('Beratungsbrief nur in dieser Demo aktualisiert.','Advisory brief updated in this demo only.'))}else if(a==='appointment'){modal(t('Beratungstermin · Demo','Advisory appointment · Demo'),`<p>${t('Dies sind fiktive Zeitfenster, keine buchbaren Termine. Wähle eines, um den Ablauf zu testen.','These are fictional slots, not bookable appointments. Choose one to test the flow.')}</p><label class="field">${t('Beispiel-Zeitfenster','Sample time slot')}<select id="appointment-slot"><option>${t('Dienstag · 10:00 · Online','Tuesday · 10:00 · Online')}</option><option>${t('Donnerstag · 14:30 · Online','Thursday · 14:30 · Online')}</option></select></label>`,button(t('Auswahl simulieren','Simulate selection'),'book-demo'))}else if(a==='book-demo'){let slot=document.getElementById('appointment-slot').value;closeModal();toast(t('Demo-Auswahl: ','Demo selection: ')+slot+t(' — nicht gebucht.',' — not booked.'))}else if(a==='document'||a==='contract'){modal(a==='contract'?t('Mustervertrag','Sample contract'):docNames()[Number(v)||0],`<div class="document-preview"><span class="eyebrow">STUDIENKOLLEG AACHEN · DEMO</span><h3>${a==='contract'?t('Vertragsvorschau','Contract preview'):docNames()[Number(v)||0]}</h3><div class="watermark">MUSTER</div><p>${t('Fiktive Vorschau ohne persönliche Daten, Vertragsbedingungen oder Rechtswirkung.','Fictional preview without personal data, contractual terms or legal effect.')}</p><hr><p>${t('Aktenreferenz: DEMO-001 · Prüfstatus: offen','Record reference: DEMO-001 · Review status: pending')}</p></div>`)}else if(a==='message'){const value=document.getElementById('demo-message').value.trim();if(!value)return toast(t('Bitte eine fiktive Nachricht eingeben.','Please enter a fictional message.'));document.getElementById('demo-message').value='';toast(t('Antwort im Demo-Ablauf simuliert. Nicht versendet.','Reply simulated. Not sent.'))}else if(a==='attendance-save'){toast(t('Anwesenheit im Demo-Zustand bestätigt — keine echte Speicherung.','Attendance confirmed in demo state — no real record saved.'))}else if(a==='case'){modal(t('Bewerbungsprüfung · ','Application review · ')+v,`<p>${t('Fiktiver Fall · T-Kurs · Nur Demonstrationsdaten.','Fictional case · T programme · Demo data only.')}</p><div class="task-row"><strong>${t('Notenübersicht','Transcript')}</strong>${badge(t('Nachforderung offen','Additional document pending'))}</div><div class="task-row"><strong>${t('Fachliche Eignung','Academic eligibility')}</strong>${badge(t('Menschliche Prüfung erforderlich','Human review required'),'blue')}</div><label class="field" style="margin-top:18px">${t('Begründung · nur Demo','Reason · demo only')}<textarea id="case-reason" placeholder="${t('Fiktive Begründung …','Fictional reason …')}"></textarea></label>`,button(t('Nachforderung simulieren','Simulate document request'),'case-request','secondary')+button(t('Prüfentscheidung simulieren','Simulate review decision'),'case-decision'))}else if(a==='case-request'||a==='case-decision'){const reason=document.getElementById('case-reason').value.trim();if(!reason)return toast(t('Bitte zuerst eine fiktive Begründung ergänzen.','Please add a fictional reason first.'));closeModal();toast(t('Prüfschritt simuliert. Keine echte Freigabe oder Nachricht.','Review step simulated. No actual approval or message.'))}else if(a==='housing'){modal(t('Wohnanfrage · Demo','Housing enquiry · Demo'),`<p>${t('Eine Anfrage ist keine Reservierung. Im Pilot werden weder Verfügbarkeit noch Mietpreise behauptet.','An enquiry is not a reservation. This pilot makes no claims about availability or rent.')}</p><label class="field">${t('Bedarf · fiktiv','Need · fictional')}<select><option>${t('Zimmer für die Vorbereitungszeit','Room during preparation')}</option><option>${t('Beratung zur Unterkunft','Accommodation advice')}</option></select></label>`,button(t('Demo-Bedarf vormerken','Note demo need'),'housing-save'))}else if(a==='housing-save'){closeModal();toast(t('Demo-Bedarf vorgemerkt. Keine Anfrage versendet, kein Zimmer reserviert.','Demo need noted. No enquiry sent or room reserved.'))}else if(a==='lms'){modal('OpenOLAT · '+t('Integrationsvorschau','Integration preview'),`<p>${t('Hier würde ein freigegebener Zugang zum Lernsystem erscheinen. Der Pilot stellt keine Verbindung zu OpenOLAT her und behauptet keine technische Freischaltung.','An approved learning-system access point would appear here. This pilot does not connect to OpenOLAT or claim technical access.')}</p><div class="task-row"><strong>${t('Mathematik · Übung 01','Mathematics · exercise 01')}</strong>${badge(t('Musterinhalt','Sample content'),'blue')}</div><p style="margin-top:20px">${t('Demo-Aufgabe: Beschreibe den Unterschied zwischen einer linearen und einer quadratischen Funktion.','Demo exercise: describe the difference between a linear and a quadratic function.')}</p>`)}else if(a==='classbook'){modal(t('Klassenbuch · Demo','Classbook · Demo'),`<label class="field">${t('Unterrichtsinhalt','Lesson content')}<textarea>${t('Beispiel: Lineare Funktionen, gemeinsame Übung und Hausaufgabe.','Example: linear functions, guided practice and homework.')}</textarea></label><p>${t('Nur ein lokaler Beispielentwurf — kein offizieller Klassenbucheintrag.','A local sample draft only — not an official classbook entry.')}</p>`,button(t('Entwurf simulieren','Simulate draft'),'generic-save'))}else if(a==='generic-save'){closeModal();toast(t('Demo-Schritt abgeschlossen. Keine Produktivdaten geändert.','Demo step complete. No production data changed.'))}else if(a==='grade'){modal(t('Bewertung & Veröffentlichung','Assessment & publication'),`<ol><li>${t('Lehrkraft erstellt Bewertungsentwurf.','Teacher prepares assessment draft.')}</li><li>${t('Zuständige Fachrolle prüft erforderliche Freigaben.','Authorised staff review required approvals.')}</li><li>${t('Nur freigegebene Ergebnisse werden veröffentlicht.','Only approved results are published.')}</li></ol>${notice(t('Der Pilot veröffentlicht keine Noten.','This pilot does not publish grades.'))}`)}else if(a==='arrival'){modal(t('Ankunftscheck · Demo','Arrival checklist · Demo'),`<ul class="check-list"><li>${t('Einreiseplanung besprechen','Discuss arrival plans')}</li><li>${t('Erforderliche Nachweise klären','Clarify required evidence')}</li><li>${t('Unterkunft separat anfragen','Enquire about housing separately')}</li><li>${t('Selbstauskunft von bestätigtem Nachweis unterscheiden','Distinguish self-reported details from verified evidence')}</li></ul>${notice(t('Behördliche Entscheidungen bleiben bei der zuständigen Behörde.','Official decisions remain with the relevant authority.'))}`)}else if(a==='exam'){modal(t('Prüfungswege · Orientierung','Exam pathways · orientation'),`<p>${t('ÖSD: Anmeldung und Freigabe hängen unter anderem von Zahlung und Kapazität ab. TestDaF und digitaler TestAS haben eigene Anbieterprozesse.','ÖSD: registration and approval depend on payment and capacity, among other factors. TestDaF and digital TestAS have their own provider processes.')}</p>${notice(t('Kein lokaler Checkout, keine erfundenen Termine oder Plätze. Die Beratung bestätigt den aktuellen Buchungsweg.','No local checkout, invented dates or places. Advisers confirm the current booking process.'))}`)}else if(a==='privacy'){modal(t('Datenschutz im Konzeptpilot','Privacy in this concept pilot'),`<p>${t('Diese Oberfläche sendet keine Formulare, Chattexte oder Dokumente an einen Backend-Dienst. Eingaben bleiben im Arbeitsspeicher dieser geöffneten Seite und verschwinden beim Neuladen. Es gibt keine echte Anmeldung oder Zugriffskontrolle.','This interface does not send forms, chat text or documents to a backend service. Entries stay in the memory of this open page and disappear when reloaded. There is no real login or access control.')}</p><p>${t('Bitte keine echten personenbezogenen Daten eingeben. Hosting kann technisch erforderliche Zugriffsdaten verarbeiten; dies ist keine vollständige Datenschutzerklärung für einen späteren Produktivbetrieb.','Please do not enter real personal data. Hosting may process technically necessary access data; this is not a complete privacy notice for a future production service.')}</p>`)}else if(a==='workflow')workflowModal();else if(a==='workflow-save'){closeModal();toast(t('Workflow-Konfiguration lokal simuliert. Keine Agenten gestartet.','Workflow configuration simulated locally. No agents started.'))}}
function workflowModal(){modal(t('Workflow-Baustein · Aufnahme','Workflow component · Admissions'),`<p>${t('Wiederverwendbare Vorlage mit geplanten Fachagenten. Keine Agentenausführung im Pilot.','Reusable template with planned specialist agents. No agent execution in this pilot.')}</p><div class="task-row"><strong>01 · ${t('Unterlagen strukturieren','Structure documents')}</strong>${badge(t('Dokumentenagent · geplant','Document agent · planned'),'blue')}</div><div class="task-row"><strong>02 · ${t('Prüfvorschlag vorbereiten','Prepare review suggestion')}</strong>${badge(t('Aufnahmeagent · geplant','Admissions agent · planned'),'blue')}</div><div class="task-row"><strong>03 · ${t('Menschliche Entscheidung','Human decision')}</strong>${badge(t('Pflichtfreigabe','Required approval'))}</div><label class="field" style="margin-top:20px">${t('Nachforderung im Demo-Ablauf','Document request in demo flow')}<select><option>${t('Vor fachlicher Prüfung','Before eligibility review')}</option><option>${t('Nach Erstberatung','After initial guidance')}</option></select></label>${notice(t('REQ-ADM-01 → WorkflowPanel → CASE-01. Geheimnisse, Zugänge und Fachfreigaben sind nicht Bestandteil der Simulation.','REQ-ADM-01 → WorkflowPanel → CASE-01. Secrets, access rights and professional approvals are outside this simulation.'))}`,button(t('Konfiguration simulieren','Simulate configuration'),'workflow-save'))}
const oldAdmin=admin;admin=function(view){return oldAdmin(view)+`<div class="panel" style="margin-top:22px"><span class="eyebrow">${t('Wiederverwendbare Prozessbausteine','Reusable process components')}</span><h3>${t('Ein Workflow. Klare Verantwortung.','One workflow. Clear responsibility.')}</h3><p>${t('Dokumentenagent → Aufnahmeagent → menschliche Freigabe. Geplante Fachagenten sind ausdrücklich keine aktiven Systeme.','Document agent → admissions agent → human approval. Planned specialist agents are explicitly not active systems.')}</p>${button(t('Workflow-Builder öffnen','Open workflow builder'),'workflow','secondary')}</div>`};
window.addEventListener('hashchange',()=>{const match=route().match(/course=([^&]+)/);if(match)state.application.course=decodeURIComponent(match[1]);render();window.scrollTo(0,0)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();document.querySelector('.assistant')?.classList.remove('open')}if(e.key==='Tab'&&document.querySelector('.modal')){const list=[...document.querySelector('.modal').querySelectorAll('button,a,input,select,textarea')];const first=list[0],last=list[list.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
render();
